def cari_terputar(nums, target):
    kiri, kanan = 0, len(nums) - 1
    while kiri <= kanan:
        tengah = (kiri + kanan) // 2
        if nums[tengah] == target:
            return tengah
        if nums[kiri] <= nums[tengah]:
            if nums[kiri] <= target < nums[tengah]:
                kanan = tengah - 1
            else:
                kiri = tengah + 1
        else:
            if nums[tengah] < target <= nums[kanan]:
                kiri = tengah + 1
            else:
                kanan = tengah - 1
    return -1
